//! Completeness: a proof generated by the prover must verify.

use galois_ring::{R2TeichmullerSampler, GR32_128, GR32_4};
use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};

use sumcheck_ring::{prove, verify, Mle};

fn rand_r2(rng: &mut StdRng) -> GR32_128 {
    let mut arr = [GR32_4::ZERO; 32];
    for slot in arr.iter_mut() {
        *slot = GR32_4([rng.gen(), rng.gen(), rng.gen(), rng.gen()]);
    }
    GR32_128(arr)
}

fn hypercube_triple(f1: &Mle, f2: &Mle, f3: &Mle) -> GR32_128 {
    assert_eq!(f1.len(), f2.len());
    assert_eq!(f1.len(), f3.len());
    let mut acc = GR32_128::ZERO;
    for i in 0..f1.len() {
        acc = acc + f1.evals()[i] * f2.evals()[i] * f3.evals()[i];
    }
    acc
}

fn round_trip_at(num_vars: usize, seed: u64) {
    let mut rng = StdRng::seed_from_u64(seed);
    let n = 1usize << num_vars;
    let f1 = Mle::new((0..n).map(|_| rand_r2(&mut rng)).collect());
    let f2 = Mle::new((0..n).map(|_| rand_r2(&mut rng)).collect());
    let f3 = Mle::new((0..n).map(|_| rand_r2(&mut rng)).collect());

    let claim = hypercube_triple(&f1, &f2, &f3);

    let mut prover_sampler = R2TeichmullerSampler::new(0xC0FFEE ^ seed);
    let (proof, prover_challenges) = prove(&f1, &f2, &f3, claim, &mut prover_sampler);

    let mut verifier_sampler = R2TeichmullerSampler::new(0xC0FFEE ^ seed);
    let verifier_challenges = verify(&proof, num_vars, &mut verifier_sampler).expect("verify");

    assert_eq!(
        prover_challenges, verifier_challenges,
        "prover and verifier challenge sequences must agree"
    );
    assert_eq!(proof.num_rounds(), num_vars);
}

#[test]
fn round_trip_4_vars() {
    round_trip_at(4, 0xa);
}

#[test]
fn round_trip_8_vars() {
    round_trip_at(8, 0xb);
}

#[test]
fn round_trip_12_vars() {
    round_trip_at(12, 0xc);
}

#[test]
fn round_trip_with_zero_factor_yields_zero_claim() {
    let mut rng = StdRng::seed_from_u64(7);
    let n = 1usize << 6;
    let f1 = Mle::new((0..n).map(|_| rand_r2(&mut rng)).collect());
    let f2 = Mle::new((0..n).map(|_| rand_r2(&mut rng)).collect());
    let f3 = Mle::new(vec![GR32_128::ZERO; n]);

    let mut sampler = R2TeichmullerSampler::new(42);
    let (proof, _) = prove(&f1, &f2, &f3, GR32_128::ZERO, &mut sampler);

    let mut sampler2 = R2TeichmullerSampler::new(42);
    verify(&proof, 6, &mut sampler2).expect("zero claim must verify");
}
